pub async fn evaluate_input(&self, text: &str) -> GuardrailDecision {
    if !self.is_enabled() || self.input.is_empty() { return Allow; }
    let mut warns = Vec::new();
    let mut current = text.to_string();
    let mut rewritten = false;
    for g in &self.input {
        let d = g.evaluate_input(&current).await;
        match d { Allow => continue, Warn { reason } => ..., Sanitize(rep) => ..., Block { .. } => return d }
    }
    settle_chain(rewritten, warns, current)
}
